import {setupGravityStudio} from './gravity-studio.js';
import * as T from './assets/three.module.js';
import {fallTime} from './dynamics.js';
import {escapeVelocityKmS,solarIrradiance} from './science.js';
const $=s=>document.querySelector(s),fmt=(n,d=2)=>n.toLocaleString('en-US',{maximumFractionDigits:d});
export function setupAnalysis(api,gfx){setupGravityStudio(api,gfx);setupComparison(api,gfx);setupData(api);}
function createScene(root,gfx){const renderer=gfx.rendererFor(root),scene=new T.Scene(),camera=new T.PerspectiveCamera(40,1,.01,1000);gfx.observeSize(root,renderer,camera);gfx.addLights(scene);let visible=false;new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(root);let last=0;const callbacks=[];function loop(now){requestAnimationFrame(loop);const dt=Math.min((now-last)/1000,.05)||0;last=now;if(!visible||document.hidden)return;for(const fn of callbacks)fn(dt,now);renderer.render(scene,camera)}requestAnimationFrame(loop);renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();root.innerHTML='<p class="fallback-message">3D context unavailable. Numerical comparison remains available.</p>'});return {scene,camera,tick:fn=>callbacks.push(fn)};}
function setupComparison(api,gfx){
 const article=$('.planet-comparison'),options=api.planets.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('');const tool=document.createElement('div');tool.className='data-toolbar';tool.innerHTML=`<label>World A<select id="compare-a">${options}</select></label><label>World B<select id="compare-b">${options}</select></label>`;$('#comparison-title').after(tool);$('#compare-a').value=2;$('#compare-b').value=3;
 const shell=document.createElement('div');shell.className='scene-shell';shell.innerHTML='<div id="comparison-scene" class="science-scene" tabindex="0" role="img" aria-label="True relative diameter comparison. Drag left or right world to rotate; arrow keys rotate selected world."></div><div class="scene-actions"><button id="comparison-reset">Reset rotation</button><label class="sync-options"><input id="comparison-sync" type="checkbox" checked> Synchronized rotation</label></div>';tool.after(shell);
 const models=[gfx.world(api.planets[2],64),gfx.world(api.planets[3],64)];let scene;try{scene=createScene($('#comparison-scene'),gfx)}catch(e){$('#comparison-scene').innerHTML='<p class="fallback-message">3D unavailable; exact numerical ratios follow below.</p>';}
 if(scene){scene.camera.position.set(0,.5,9);scene.camera.lookAt(0,0,0);models.forEach(m=>scene.scene.add(m.group));}
 function update(){const a=api.planets[+$('#compare-a').value],b=api.planets[+$('#compare-b').value],max=Math.max(a.diameter,b.diameter);models.forEach((m,i)=>{const p=i?b:a;m.setPlanet(p);m.group.scale.setScalar(p.diameter/max*.83);m.group.position.x=i?1.5:-1.5;m.atmosphere.visible=false;m.cloud.visible=p.name==='Earth';});$('#comparison-title').textContent=a.name.toUpperCase()+' / '+b.name.toUpperCase();$('#comparison-metrics').innerHTML=[['Diameter',a.diameter,b.diameter,'km'],['Gravity',a.gravity,b.gravity,'m/s²'],['Escape speed',escapeVelocityKmS(a.gravity,a.diameter),escapeVelocityKmS(b.gravity,b.diameter),'km/s'],['Orbital period',a.period,b.period,'d'],['Mean temperature',a.temp,b.temp,'°C'],['Solar irradiance',solarIrradiance(a.distance),solarIrradiance(b.distance),'W/m²']].map(([k,x,y,u])=>`<div class="comparison-metric"><div><span>${k}</span><strong>${fmt(x)} / ${fmt(y)} ${u}</strong></div></div>`).join('');article.querySelector('.instrument-note').textContent='TRUE RELATIVE DIAMETERS · DRAG EITHER WORLD TO ROTATE';}
 $('#compare-a').onchange=()=>{update();api.selectPlanet(+$('#compare-a').value)};$('#compare-b').onchange=update;document.addEventListener('planet-change',()=>{$('#compare-a').value=api.getState().current;update()});
 let drag=false,last=0,side=0;const root=$('#comparison-scene');root.onpointerdown=e=>{drag=true;last=e.clientX;side=e.offsetX>root.clientWidth/2?1:0;root.setPointerCapture(e.pointerId)};root.onpointermove=e=>{if(!drag)return;const delta=(e.clientX-last)*.01;models.forEach((m,i)=>{if($('#comparison-sync').checked||i===side)m.globe.rotation.y+=delta});last=e.clientX};root.onpointerup=root.onpointercancel=()=>drag=false;root.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();models.forEach((m,i)=>{if($('#comparison-sync').checked||i===side)m.globe.rotation.y+=e.key==='ArrowLeft'?-.1:.1})}};$('#comparison-reset').onclick=()=>models.forEach(m=>m.globe.rotation.y=0);update();
 // Preserve the original full-screen comparison action, using the selected world A.
}
function setupData(api){
 const controls=document.createElement('div');controls.className='data-toolbar';controls.innerHTML='<label>Metric<select id="analysis-metric"><option value="distance">Solar distance</option><option value="diameter">Equatorial diameter</option><option value="gravity">Gravity</option><option value="escape">Escape velocity</option><option value="period">Orbital period</option><option value="temp">Mean temperature</option><option value="irradiance">Solar irradiance</option></select></label><label>Scale<select id="analysis-scale"><option value="linear">Linear</option><option value="log">Logarithmic</option></select></label><label>Sort<select id="analysis-sort"><option value="orbital">Orbital order</option><option value="ascending">Ascending value</option><option value="descending">Descending value</option></select></label><label>Filter<select id="analysis-filter"><option value="all">All planets</option><option value="rocky">Rocky planets</option><option value="giants">Gas / ice giants</option><option value="pair">Compare selected pair</option></select></label><label>Distance unit<select id="analysis-unit"><option value="km">Kilometers</option><option value="au">Astronomical units</option></select></label>';
 $('.lab .section-heading').after(controls);const card=document.createElement('article');card.className='chart-card';card.innerHTML='<div class="chart-heading"><h3 id="analysis-heading">Solar distance</h3></div><p id="analysis-definition"></p><div id="analysis-rows" class="analytic-rows" aria-label="Interactive planetary metric chart"></div><div class="chart-foot"><span id="analysis-foot"></span><span>SELECT A ROW TO LINK THE OBSERVATORY</span></div>';controls.after(card);$('.charts').style.marginTop='24px';
 const definitions={distance:['Solar distance','Mean heliocentric distance. The dated orbital engine shows changing positions.'],diameter:['Equatorial diameter','Width across the equator; not polar diameter.'],gravity:['Gravity','Reference gravitational acceleration. Gas giants use an atmospheric reference level.'],escape:['Escape velocity','Idealized √(2gR), neglecting rotation and atmosphere.'],period:['Orbital period','Sidereal orbital period, rounded in Earth days.'],temp:['Mean temperature','A rounded mean or atmospheric reference temperature; not a map or daily forecast.'],irradiance:['Solar irradiance','Inverse-square estimate: 1361 W/m² at 1 AU; no atmospheric attenuation.']};
 const unit=()=>document.querySelector('[data-unit][aria-pressed=true]')?.dataset.unit||'C';
 function render(){const key=$('#analysis-metric').value,u=unit(),au=$('#analysis-unit').value==='au';let measure=p=>p[key];let suffix={distance:au?'AU':'km',diameter:'km',gravity:'m/s²',escape:'km/s',period:'d',temp:'°'+u,irradiance:'W/m²'}[key];if(key==='distance')measure=p=>au?p.distance/149.5978707:p.distance*1e6;if(key==='temp')measure=p=>u==='F'?p.temp*1.8+32:p.temp;if(key==='escape')measure=p=>escapeVelocityKmS(p.gravity,p.diameter);if(key==='irradiance')measure=p=>solarIrradiance(p.distance);
  const log=$('#analysis-scale').value==='log',filter=$('#analysis-filter').value,sort=$('#analysis-sort').value,a=+$('#compare-a').value,b=+$('#compare-b').value;const rows=api.planets.map((p,i)=>({p,i,v:measure(p)})).filter(x=>filter==='all'||filter==='rocky'&&x.i<4||filter==='giants'&&x.i>=4||filter==='pair'&&[a,b].includes(x.i));if(sort!=='orbital')rows.sort((a,b)=>(a.v-b.v)*(sort==='ascending'?1:-1));const values=rows.map(x=>x.v),canLog=values.every(x=>x>0);const useLog=log&&canLog,transform=x=>useLog?Math.log10(x):x,min=Math.min(0,...values.map(transform)),max=Math.max(...values.map(transform));
  $('#analysis-heading').textContent=definitions[key][0];$('#analysis-definition').textContent=definitions[key][1]+(log&&!canLog?' Log scale is unavailable for zero or negative values; showing linear.':'');$('#analysis-foot').textContent=(useLog?'LOGARITHMIC':'LINEAR')+' · '+suffix;
  $('#analysis-rows').innerHTML=rows.map(({p,i,v})=>`<button class="analytic-row ${i===api.getState().current?'selected':''}" data-planet="${i}" aria-pressed="${i===api.getState().current}" title="${p.name}: ${fmt(v)} ${suffix}. ${definitions[key][1]}" aria-label="${p.name}, ${fmt(v)} ${suffix}"><span>${p.name}</span><span class="metric-track"><span class="metric-bar" style="width:${Math.max(1,(transform(v)-min)/(max-min||1)*100)}%"></span></span><output>${fmt(v)} ${suffix}</output></button>`).join('');
 }
 controls.querySelectorAll('select').forEach(x=>x.onchange=render);document.addEventListener('planet-change',render);document.querySelectorAll('[data-unit]').forEach(x=>x.addEventListener('click',render));$('#compare-b').addEventListener('change',render);render();
}
